function decodeValue(d, v) {
  if (typeof d === "string" || v === null) return v;
  switch (d[0]) {
    case "enum": return ENUMS[d[1]][v];
    case "opt": return decodeValue(d[1], v);
    case "struct": {
      const fields = TYPES[d[1]];
      const o = {};
      for (let i = 0; i < fields.length; i++) o[fields[i][0]] = decodeValue(fields[i][1], v[i]);
      return o;
    }
    case "list": return v.map((e) => decodeValue(["struct", d[1]], e[1]));
    default: throw new Error("bad type descriptor " + JSON.stringify(d));
  }
}

const PATH_IDS = new Map(PATHS.map((p, i) => [p.path, i]));

/** The field id of a path such as `top.gold` or `top.resources[].name`, or -1. */
export function fieldId(path) {
  const id = PATH_IDS.get(path);
  return id === undefined ? -1 : id;
}

/**
 * Decode a UMD1 text (a frame delta or a snapshot) into `{revision, ops}`. Ops are objects with `op` one of
 * `set`, `insert`, `remove`, `move`, `reset`; values are decoded by the schema (structs to objects, enums to
 * names, lists to arrays of elements). Throws if the text was built for another schema.
 */
export function decodeUmd1(text) {
  const a = JSON.parse(text);
  const ops = [];
  for (let i = 1; i < a.length; i++) {
    const o = a[i];
    switch (o[0]) {
      case 0: {
        const p = PATHS[o[1]];
        ops.push({ op: "set", field: o[1], path: p.path, keys: o[2], value: decodeValue(p.type, o[3]) });
        break;
      }
      case 1: {
        const p = PATHS[o[1]];
        ops.push({ op: "insert", field: o[1], path: p.path, keys: o[2], at: o[3], key: o[4],
          value: decodeValue(["struct", p.type[1]], o[5]) });
        break;
      }
      case 2: {
        const p = PATHS[o[1]];
        ops.push({ op: "remove", field: o[1], path: p.path, keys: o[2], key: o[3] });
        break;
      }
      case 3: {
        const p = PATHS[o[1]];
        ops.push({ op: "move", field: o[1], path: p.path, keys: o[2], key: o[3], to: o[4] });
        break;
      }
      case 4:
        ops.push({ op: "reset", root: ROOTS[o[1]][0], value: decodeValue(ROOTS[o[1]][1], o[2]) });
        break;
      case 5:
        if (o[1] !== SCHEMA_HASH) {
          throw new Error("model schema mismatch: delta " + o[1] + ", client " + SCHEMA_HASH);
        }
        break;
      default:
        throw new Error("unknown UMD1 op " + o[0]);
    }
  }
  return { revision: a[0], ops };
}
